begin;
select plan(33);
insert into auth.users(id,email) values ('c1000000-0000-4000-a000-000000000001','r3-a@example.test'),('c1000000-0000-4000-a000-000000000002','r3-b@example.test');
insert into public.food_concepts(id,slug,display_name) values ('c2000000-0000-4000-a000-000000000001','r3-queso','Queso R3'),('c2000000-0000-4000-a000-000000000002','r3-tomate','Tomate R3');
insert into public.recipe_import_jobs(id,user_id,idempotency_key,source_type,manual_text,state,result) values
 ('c3000000-0000-4000-a000-000000000001','c1000000-0000-4000-a000-000000000001','r3-completed-import','manual','receta ejemplo','completed','{"schemaVersion":"recipe-v1","title":"Rolls R3","ingredients":[{"name":"Queso R3","amount":"300","unit":"g"},{"name":"Tomate R3"},{"name":"No resuelto R3"}],"steps":["Enrollar"],"source":{"type":"manual"},"provenance":{"sourceType":"manual","quality":{"status":"review_required"}}}');
insert into public.recipe_import_jobs(id,user_id,idempotency_key,source_type,manual_text,state,retryable,error_code) values
 ('c3000000-0000-4000-a000-000000000002','c1000000-0000-4000-a000-000000000001','r3-failed-import-1','manual','receta ejemplo','failed',true,'WHISPER_TIMEOUT');
insert into public.recipe_import_jobs(id,user_id,idempotency_key,source_type,upload_object,state,retryable) values
 ('c3000000-0000-4000-a000-000000000003','c1000000-0000-4000-a000-000000000001','r3-failed-import-2','file','cleaned-upload','failed',true);
insert into public.inventory_items(id,user_id,name,expiry_date,quantity,unit,added_at,food_concept_id,normalization_status,normalization_source,knowledge_provenance,stock_mode,stock_state,quantity_precision,quantity_exact,quantity_unit) values
 ('c4000000-0000-4000-a000-000000000001','c1000000-0000-4000-a000-000000000001','Queso R3','2026-10-20',200,'g',now(),'c2000000-0000-4000-a000-000000000001','confirmed','user','user','exact','some','exact',200,'g');
create temp table r3_tokens(cache jsonb,version text,key text);
grant all on r3_tokens to authenticated;
insert into r3_tokens(version,key) select r->>'recipeVersion',public.cook_state_key_v1('c1000000-0000-4000-a000-000000000001','import','c3000000-0000-4000-a000-000000000001') from (select public.cook_recipe_for_user_v1('c1000000-0000-4000-a000-000000000001','import','c3000000-0000-4000-a000-000000000001') r) s;
update r3_tokens set cache=public.store_cook_cache_v1('c1000000-0000-4000-a000-000000000001','import','c3000000-0000-4000-a000-000000000001',key,version,'{"clientForgedPlan":["No resuelto R3"]}');
select ok(not has_function_privilege('authenticated','public.store_cook_cache_v1(uuid,text,uuid,text,text,jsonb)','EXECUTE'),'browser cannot publish a plan');
select ok(not has_function_privilege('authenticated','public.cook_recipe_for_user_v1(uuid,text,uuid)','EXECUTE'),'private arbitrary-user helper is hidden');
select ok(not has_table_privilege('authenticated','public.cook_availability_cache','INSERT'),'cache writes privileged');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1000000-0000-4000-a000-000000000001","role":"authenticated"}',true);
select is(public.read_cook_context_v1('import','c3000000-0000-4000-a000-000000000001')#>>'{recipe,title}','Rolls R3','own import readable');
select is(public.read_cook_context_v1('import','c3000000-0000-4000-a000-000000000001')#>>'{recipe,reviewRequired}','true','provisional evidence preserved');
select is(jsonb_array_length(public.read_cook_library_v1()->'jobs'),3,'library returns own completed and failed imports');
select is(public.apply_cook_mutation_v1('shopping','import','c3000000-0000-4000-a000-000000000001',(select cache->>'snapshotKey' from r3_tokens),'c5000000-0000-4000-a000-000000000001')->>'status','applied','atomic shopping applies');
select is((select count(*) from public.shopping_list_items),2::bigint,'unknown concept not added; two demonstrated deficits');
select is((select quantity from public.shopping_list_items where ingredient_key='c2000000-0000-4000-a000-000000000001'),100::numeric,'SQL recomputes exact deficit');
select is((select quantity from public.shopping_list_items where ingredient_key='c2000000-0000-4000-a000-000000000002'),null::numeric,'absent ingredient never fabricated as quantity one');
select is((select source_ref from public.shopping_list_items limit 1),'import:c3000000-0000-4000-a000-000000000001','origin namespaced by private job');
select is(public.apply_cook_mutation_v1('shopping','import','c3000000-0000-4000-a000-000000000001',(select cache->>'snapshotKey' from r3_tokens),'c5000000-0000-4000-a000-000000000001')->>'status','duplicate','same attempt replays');
select is(public.apply_cook_mutation_v1('shopping','import','c3000000-0000-4000-a000-000000000001',(select cache->>'snapshotKey' from r3_tokens),'c5000000-0000-4000-a000-000000000002')->>'status','applied','another deliberate gesture allowed');
select is((select count(*) from public.shopping_list_items),2::bigint,'different gesture deduplicates active origin items');
select is(public.apply_cook_mutation_v1('save','import','c3000000-0000-4000-a000-000000000001',(select version from r3_tokens),'c5000000-0000-4000-a000-000000000001')->>'error','MUTATION_CONFLICT','mutation cannot change operation');
select is(public.apply_cook_mutation_v1('save','import','c3000000-0000-4000-a000-000000000001',(select version from r3_tokens),'c5000000-0000-4000-a000-000000000003')->>'status','applied','import save requires no catalog insertion');
select is(public.apply_cook_mutation_v1('save','import','c3000000-0000-4000-a000-000000000001',(select version from r3_tokens),'c5000000-0000-4000-a000-000000000004')->>'status','applied','save second gesture is idempotent');
select is((select count(*) from public.favorite_recipes),1::bigint,'one favorite per import');
select is((select snapshot->>'reviewRequired' from public.favorite_recipes limit 1),'true','saved provisional warning persists');
select is(public.retry_recipe_import_v1('c3000000-0000-4000-a000-000000000002')->>'generation','1','retry same job increments generation');
select is(public.retry_recipe_import_v1('c3000000-0000-4000-a000-000000000002')->>'replay','true','retry concurrent gesture deduplicates');
select is(public.retry_recipe_import_v1('c3000000-0000-4000-a000-000000000003')->>'error','RETRY_NOT_AVAILABLE','cleaned file source not retryable');
select is((select count(*) from public.recipe_import_usage),0::bigint,'no import quota mutations');
reset role;
update public.inventory_items set quantity_exact=400,quantity=400,version=version+1 where id='c4000000-0000-4000-a000-000000000001';
set local role authenticated;
select is(public.apply_cook_mutation_v1('shopping','import','c3000000-0000-4000-a000-000000000001',(select cache->>'snapshotKey' from r3_tokens),'c5000000-0000-4000-a000-000000000001')->>'status','duplicate','replay precedes current pantry validation');
select is(public.apply_cook_mutation_v1('shopping','import','c3000000-0000-4000-a000-000000000001',(select cache->>'snapshotKey' from r3_tokens),'c5000000-0000-4000-a000-000000000005')->>'error','SNAPSHOT_CONFLICT','new gesture rejects outdated pantry');
reset role;
insert into public.recipe_import_revisions(job_id,user_id,version,result) select id,user_id,1,jsonb_set(result,'{title}','"Rolls revisados R3"') from public.recipe_import_jobs where id='c3000000-0000-4000-a000-000000000001';
set local role authenticated;
select is(public.apply_cook_mutation_v1('save','import','c3000000-0000-4000-a000-000000000001',(select version from r3_tokens),'c5000000-0000-4000-a000-000000000006')->>'error','RECIPE_CONFLICT','old recipe version rejects save');
select is((select snapshot->>'title' from public.favorite_recipes limit 1),'Rolls R3','accepted revision leaves favorite snapshot immutable');
select is(public.read_cook_context_v1('import','c3000000-0000-4000-a000-000000000001')#>>'{recipe,title}','Rolls revisados R3','latest accepted revision is projected');
select is(public.read_cook_context_v1('import','c3000000-0000-4000-a000-000000000001')->'cached','null'::jsonb,'recipe revision invalidates availability cache');
reset role;
insert into public.recipe_import_revisions(job_id,user_id,version,result) values('c3000000-0000-4000-a000-000000000001','c1000000-0000-4000-a000-000000000001',2,'{"schemaVersion":"recipe-v1","title":"Invalid ingredients","ingredients":[{"name":false}],"steps":["Step"]}');
set local role authenticated;
select is(public.read_cook_context_v1('import','c3000000-0000-4000-a000-000000000001')->>'error','RECIPE_INVALID','completed with invalid revision blocks projection');
select is(public.apply_cook_mutation_v1('save','import','c3000000-0000-4000-a000-000000000001',(select version from r3_tokens),'c5000000-0000-4000-a000-000000000007')->>'error','RECIPE_INVALID','invalid recipe cannot be saved');
select set_config('request.jwt.claims','{"sub":"c1000000-0000-4000-a000-000000000002","role":"authenticated"}',true);
select is(public.read_cook_context_v1('import','c3000000-0000-4000-a000-000000000001')->>'error','RECIPE_NOT_FOUND','other user sees uniform 404');
select is((select count(*) from public.cook_availability_cache),0::bigint,'RLS excludes other cache');
select * from finish();
rollback;
